    public void TbdVerschilOptellen(BXtoKst xtokstErbij, BXtoKst xtokstEraf)
    {
        if (m_Vlt != xtokstErbij.m_Vlt || m_Vlt != xtokstEraf.m_Vlt)
            throw new OngelijkeValutaException();

        Debug.Assert(xtokstErbij._Vlt == xtokstEraf._Vlt, "Ongelijke valuta");

