    /// <summary>
    /// 
    /// </summary>
    /// <param name="kst"></param>
    /// <param name="btwKst">Btw Hoog ("H") of Laag ("L") of Nul ("")</param>
    /// <param name="abWaarde">Afgeronde bruto waarde</param>
    internal void BtwWaarden(EKst kst, string btwKst, double abWaarde)
    {
        switch (btwKst)
        {
            case "H":
                m_XtoKst[(int)EXto.Bgh, (int)kst] = abWaarde;
                //m_XtoKst[(int)EXto.Bgh, (int)EKst.Aks] += abWaarde; 
                m_XtoKst[(int)EXto.Bgl, (int)kst] = 0.0;
                break;

            case "L":
                m_XtoKst[(int)EXto.Bgl, (int)kst] = abWaarde;
                //m_XtoKst[(int)EXto.Bgl, (int)EKst.Aks] += abWaarde; 
                m_XtoKst[(int)EXto.Bgh, (int)kst] = 0.0;
                break;

            default:
                m_XtoKst[(int)EXto.Bgh, (int)kst] = 0.0;
                m_XtoKst[(int)EXto.Bgl, (int)kst] = 0.0;
                break;
        }
    }

    internal void SchrijfXml(XmlWriter xmlWriter)
    {
        string[] attrNamen = { "arb", "mta", "mte", "oda" };
        for (int index = 0; index < 4; index++)
        {
            xmlWriter.WriteAttributeString("nto" + attrNamen[index], XmlConvert.ToString(m_XtoKst[(int)EXto.Nto, index]));
            xmlWriter.WriteAttributeString("bto" + attrNamen[index], XmlConvert.ToString(m_XtoKst[(int)EXto.Bto, index]));
            xmlWriter.WriteAttributeString("bgh" + attrNamen[index], XmlConvert.ToString(m_XtoKst[(int)EXto.Bgh, index]));
            xmlWriter.WriteAttributeString("bgl" + attrNamen[index], XmlConvert.ToString(m_XtoKst[(int)EXto.Bgl, index]));
        }
        xmlWriter.WriteAttributeString("ntotot", XmlConvert.ToString(m_XtoKst[(int)EXto.Nto, (int)EKst.Aks]));
        xmlWriter.WriteAttributeString("btotot", XmlConvert.ToString(m_XtoKst[(int)EXto.Bto, (int)EKst.Aks]));
    }
    public static string KstAlsString(EKst kst)
    {
        string naam;
        switch (kst)
        {
            case EKst.Arb: naam = "ARB"; break;
            case EKst.Mta: naam = "MTA"; break;
            case EKst.Mte: naam = "MTE"; break;
            case EKst.Oda: naam = "ODA"; break;
            case EKst.Str: naam = "STR"; break;
            case EKst.Aks: naam = "AKS"; break;
            // case EKst.Hvh:  naam = "HVH"; break;  EKst.Hvh == EKst.Aks
            default: throw new OnbekendeKostensoortException();
        }
        return naam;
    }
