    /// <summary>
    /// Tel de bedragen in de eerste BXtoKst op bij de huidige en
    /// trek de bedragen in de tweede BXtoKst af van de huidige
    /// </summary>
    /// <param name="xtokstErbij">De op te tellen bedragen</param>
    /// <param name="xtokstEraf">De af te trekken bedragen</param>
    public void TbdVerschilOptellen(BXtoKst xtokstErbij, BXtoKst xtokstEraf)
    {
        if (m_Vlt != xtokstErbij.m_Vlt || m_Vlt != xtokstEraf.m_Vlt)
            throw new OngelijkeValutaException();

        Debug.Assert(xtokstErbij._Vlt == xtokstEraf._Vlt, "Ongelijke valuta");

        for (int index = c_AtlKst - 1; index >= 0; index--)
        {
            m_XtoKst[(int)EXto.Nto, index] +=
               xtokstErbij.m_XtoKst[(int)EXto.Nto, index] -
               xtokstEraf.m_XtoKst[(int)EXto.Nto, index];
            m_XtoKst[(int)EXto.Bto, index] +=
               xtokstErbij.m_XtoKst[(int)EXto.Bto, index] -
               xtokstEraf.m_XtoKst[(int)EXto.Bto, index];
        }
    }
