            if (_afronden.Getal(this[EXto.Bto, EKst.Arb].Waarde, 5) != _afronden.Getal(xtoKst2[EXto.Bto, EKst.Arb].Waarde, 5)) gelijk |= EVergelijk.btoarb;
            if (_afronden.Getal(this[EXto.Bto, EKst.Mta].Waarde, 5) != _afronden.Getal(xtoKst2[EXto.Bto, EKst.Mta].Waarde, 5)) gelijk |= EVergelijk.btomta;
