        private bool KostenbestandInloggen()
        {
            if (_kostenModel.Ingelogd) return true;
            return _kostenModel.Login();
        }

        /// <summary>get/set Eigenschappen van een onderhoud kostenbestand (kostenbestand en parameters)
        /// </summary>
        public BBrinkKostenbestandEigenschappen? _BrinkKostenbestandEigenschappenOnderhoud
        {
            get
            {
                if (m_BrinkKostenbestandEigenschappenOnderhoud == null)
                {
                    BBrinkKostenbestandEigenschappen? kbEigenschappen = new(_KostenbestandEigenschappenOnderhoud, _KostenbestandOnderhoudParameters, DateTime.Now.Year);

                    if (kbEigenschappen._KostenbestandId != null)
                    {
                        if (KostenbestandInloggen())
                        {
                            if (kbEigenschappen._AltijdLaatsteVersie)
                            {
                                if (!DateTime.TryParse(_Dtm_Toonbaar, out DateTime begrotingDatum))
                                    begrotingDatum = DateTime.Now;
                                kbEigenschappen = _kostenbestandRaadplegen.LeesTegebruikenKostenBestand(kbEigenschappen, begrotingDatum.Year);
                            }
                            else
                            {
                                // Bepaal de wijzigdatum van het kostenbestan op de server
                                BKostenBestand? kostenBestand = _kostenModel?.GeefKostenBestand((Guid)kbEigenschappen._KostenbestandId);
                                if (kostenBestand?.wijzigdatum != null)
                                {
                                    if (kbEigenschappen._Wijzigdatum < kostenBestand.wijzigdatum)
                                    {
                                        kbEigenschappen._Wijzigdatum = kostenBestand.wijzigdatum;
                                        _KostenbestandEigenschappenOnderhoud = kbEigenschappen._Identificatie;
                                    }

                                }
                                else
                                {
                                    // Geen kostenbestand gevonden!!
                                    // Het aanwezige kostenbestand in tact houden.
                                }
                            }

                            if (_KostenbestandOnderhoudParameters != null)
                            {
                                m_BrinkKostenbestandEigenschappenOnderhoud = new BBrinkKostenbestandEigenschappen(kbEigenschappen?._Identificatie,
                                                                                                                  _KostenbestandOnderhoudParameters, kbEigenschappen?._MJOBJaar ?? 0);
                            }
                        }
                    }
                    m_BrinkKostenbestandEigenschappenOnderhoud = kbEigenschappen;

                }


                return m_BrinkKostenbestandEigenschappenOnderhoud;
            }
            set
            {
                m_BrinkKostenbestandEigenschappenOnderhoud = value;
            }
        }

