        public bool VerwijderKtpMiddel(BKostenpost kostenpost, bool undo)
        {
            // ga na of kostenpost._Middel nog ergens gebruikt wordt
            BMiddel middel = kostenpost._Middel;
            if (!_Umc ||                                        // geen unieke middelencodering?
               string.IsNullOrEmpty(middel._MidCde) ||         // lege middelcode
               !_Stu.ZoekMiddel(middel._Id, kostenpost._Id))   // geen andere kostenposten die dit middel toepassen
            {
                // de kostenpost had z'n eigen middel
                return _Mid.MiddelVerwijderen(middel, undo);    // dit heeft geen consequenties voor andere kostenposten
            }
            return false;
        }
