        public BOpdracht? KopieerRefRegelData(int stuIndex, IBegrotingsRegel refRegel, IBegrotingsRegel bgrRegel)
        {
            Debug.Assert(m_Stu != null);
            Debug.Assert(stuIndex >= 0);

            KopieerReferentieRegelDataOpdracht? vorigeOpdracht = _OpdrachtVzl.GeefOpdracht() as KopieerReferentieRegelDataOpdracht;

            KopieerReferentieRegelDataOpdracht opdracht = new KopieerReferentieRegelDataOpdracht(stuIndex, refRegel, bgrRegel, vorigeOpdracht);

            if (!opdracht.Uitvoeren(null!))
                return null;

            if (!m_Snel)
            {
                if (opdracht._Rekenen)
                    Rekenen(ERekendiepte.Wijzigingen);

                if (opdracht.MoetSamenvoegen)
                {
                    vorigeOpdracht?.Samenvoegen(opdracht);  // Voeg de gegevens in de vorige opdracht samen met die van de nieuwe
                }
                else
                {
                    _OpdrachtVzl.Aanmelden(opdracht);
                }
            }
            opdracht._RegelNummer = opdracht.StuIndex;
            _Context = opdracht._Context;

            return opdracht;
        }

