            Debug.Assert(koppeling._Nieuw, "MeetstaatKoppelen() - nieuw id maar geen nieuwe koppeling");
            koppeling._KoppelingId = GeefNieuwId();

            var opdracht = new MeetstaatKoppelenOpdracht(this, meetstaat, stuIndex, koppeling)
            {
                _ViewNr = _ViewNr
            };
            return _OpdrachtVzl.Uitvoeren(opdracht);
        }

