            opdracht.MiddelDoel.WijzigingInMiddel();

            BKostenpost? kostenpostDoel = _Stu[opdracht.StuIndexDoel]._Regel as BKostenpost;
            kostenpostDoel?.BgrRglGewijzigd(true);

