        /// <summary>get/set Bgv Property: Btw toepassen
        /// </summary>
        public bool _BtwToepassen
        {
            get
            {
                BBegrotingsGegeven? bgv = _Bgv.GeefBegrotingsGegeven(BBegrotingsGegeven.c_BtwToepassen);
                if (bgv != null)
                    return bgv._Wde.Length > 0 && bgv._Wde[0] == 'J';

                _BtwToepassen = false;
                return false;
            }
            set
            {
                BBegrotingsGegeven bgv = _Bgv.MaakBegrotingsGegeven(BBegrotingsGegeven.c_BtwToepassen, EGgvTpe.Tekst, "Btw toepassen");//NIETVERTALEN
                bgv._Wde = value ? "J" : "N";//NIETVERTALEN

                if (m_BtwToepassen != value)
                {
                    m_BtwToepassen = value;

                    if (m_BtwToepassen)
                    {
                        int eersteMelding = _logboek.Aantal;

                        Rekenen(ERekendiepte.Meldingen);

                        int atlMeldingen = _logboek.Aantal - eersteMelding;

                        string deelTekst;
                        if (atlMeldingen == 0)
                            deelTekst = ProjectResources.TradA002411;
                        else if (atlMeldingen == 1)
                            deelTekst = ProjectResources.TradA002412;
                        else
                            deelTekst = $"{ProjectResources.TradA002413}{BStatics.c_Spatie}{atlMeldingen}{BStatics.c_Spatie}{ProjectResources.TradA002414}";

                        _meldingVenster.ToonMelding($"{ProjectResources.TradA002415}{BStatics.c_Spatie}{deelTekst}{BStatics.c_Spatie}{ProjectResources.TradA002416}", EMessageBoxIcon.Information);
                    }
                    else
                    {
                        if (m_Bbd != null)
                            Rekenen(ERekendiepte.Meldingen);
                    }
                }
            }
        }

