        /// <summary>
        /// Wijzig UMC met gebruik van dubbele codes lijst.
        /// </summary>
        /// <param name="umc"></param>
        /// <param name="dubbeleCodes"></param>
        /// <returns></returns>
        public BOpdracht? WijzigBgrUmc(bool umc, out IList<string>? dubbeleCodes)
        {
            BWijzigUmc opdracht = new BWijzigUmc(umc);
            dubbeleCodes = null;

            if (!Uitvoeren(opdracht))
            {
                dubbeleCodes = opdracht.DubbeleCodes;
                return null;
            }
            if (umc) //bug 3815
            {
                // Er kunnen dubbele middelcodes voorkomen die wel voldoen aan
                // de voorwaarden van UMC. Comprimeer de middelen
                _Mid.Comprimeren(out List<BMiddelen.BVervangenMiddel> vervangenMiddelen);

                int stuIndex = -1;
                int middelId;
                int vervangIndex;
                BMiddelen.BVervangenMiddel zoekVervangendMiddel = new BMiddelen.BVervangenMiddel();
                BMiddel vervangendMiddel;

                // Doorloop de kostenposten en vervang de verwijderde middelen door de overgebleven.
                var kostenpost = (BKostenpost?)_Stu.GeefVolgendeBgrRegel(EOnderbouwing.Kostenpost, ref stuIndex);
                while (kostenpost != null)
                {
                    middelId = kostenpost?._Middel?._Id ?? 0;
                    zoekVervangendMiddel.m_MiddelId = middelId;

                    vervangenMiddelen.Sort();
                    vervangIndex = vervangenMiddelen.BinarySearch(zoekVervangendMiddel);

                    if (vervangIndex >= 0)
                    {
                        vervangendMiddel = vervangenMiddelen[vervangIndex].m_VervangendMiddel;
                        kostenpost?.WijzigMiddel(vervangendMiddel, true);
                    }

                    kostenpost = (BKostenpost?)_Stu.GeefVolgendeBgrRegel(EOnderbouwing.Kostenpost, ref stuIndex);
                }
            }
            _OpdrachtVzl.Aanmelden(opdracht);

            return opdracht;
        }
