        public bool MeetstaatKoppelen(int kolomNr, int regelNr, IMeetstaat meetstaat, int stuIndex)
        {
            // Als er geen kolom- ?n geen regelnummer bekend is dan wordt het een standaardkoppeling
            if (kolomNr < 0 && regelNr < 0)
                return MeetstaatKoppelen(meetstaat, stuIndex);

            // Maak de koppeling
            BMeetstaatKoppeling? koppeling = meetstaat.MaakKoppeling(kolomNr, regelNr);

            return MeetstaatKoppelen(meetstaat, stuIndex, koppeling!);
        }

        private bool MeetstaatKoppelen(IMeetstaat meetstaat, int stuIndex, BMeetstaatKoppeling koppeling)
        {
            // Controleer de begrotingsregel
            IBegrotingsRegel? bgrRegel = _Stu[stuIndex]._Regel;
            if (bgrRegel?._Koppelbaar != true)
                return false;

            Debug.Assert(koppeling._Nieuw, "MeetstaatKoppelen() - nieuw id maar geen nieuwe koppeling");
            koppeling._KoppelingId = GeefNieuwId();

            var opdracht = new MeetstaatKoppelenOpdracht(this, meetstaat, stuIndex, koppeling)
            {
                _ViewNr = _ViewNr
            };
            return _OpdrachtVzl.Uitvoeren(opdracht);
        }

