        /// Zet deze op -1 als de stuIndexDoel bekend is</param>
        public BOpdracht? KopieerBegrotingsRegels(IBegroting bgrOrig, IList<int> stuIndicesOrig, int stuIndexDoel, int eltId, bool bbdSectie)
        {
            Debug.Assert(m_Stu != null, "BBegroting.KopieerBegrotingsRegels() - geen structuurlijst");
            Debug.Assert(bgrOrig._Stu != null, "BBegroting.KopieerBegrotingsRegels() - geen structuurlijst");
            Debug.Assert((stuIndexDoel > 0 && stuIndexDoel <= _Stu._Aantal) || eltId >= BBegroting.c_RElId, "BBegroting.KopieerBegrotingsRegels() - doel-index of element-id verkeerd");

            BSelectie selectie = new BSelectie();
            foreach (int stuIndex in stuIndicesOrig)
            {
                selectie.Toevoegen(stuIndex);
            }

            KopieerBegrotingRegelsOpdracht opdracht = new KopieerBegrotingRegelsOpdracht(this, bgrOrig, selectie, bbdSectie, stuIndicesOrig);
            opdracht.StuIndexDoel = stuIndexDoel;
            opdracht.PrtIdDoel = eltId;
            return KopieerBegrotingsRegels(opdracht);
        }
