        /// <summary>
        /// Maak van een kostenpost een sjoemelpost.
        /// Een sjoemelpost is een kostenpost waarvan de hoeveelheid altijd 1 is.
        /// De materiaalprijs in het bijbehorende middel wordt gevarieerd.
        /// Op die manier kan er altijd naar een vast begrotingstotaal toe worden gerekend.
        /// Deze functie:
        /// - is zonder UNDO
        /// - als er al een sjoemelpost is dan wijzigt er niets
        /// </summary>
        /// <param name="kostenpost">De kostenpost die gebruikt zal worden om naar een vast begrotingstotaal toe te rekenen</param>
        public void LeesXmlVtt(BKostenpost kostenpost)
        {
            if (_VttId == 0)
            {
