        public bool Uitvoeren(BWijzigMiddelCode opdracht)
        {
            //Ik ben hier ook niet echt gelukkig mee: js
            if (null != MiddelBeHoudenBijGeneriekClipboard)
            {
                if (true == MiddelBeHoudenBijGeneriekClipboard)
                    MiddelBeHoudenBijGeneriekClipboard = null;
                return false;
            }
            MiddelBeHoudenBijGeneriekClipboard = null;
            /* e-mail van HvdR aan AJdH dd. 1-7-2003 over het wijzigen van middeleigenschappen:

               Zonder UMC
               Elke kostenpost heeft z'n eigen middel.
               Wijzigen van middeleigenschappen, inclusief z'n middelcode, heeft alleen betrekking op het middel bij de kostenpost.

               Met UMC
               Wijzigen van alle middeleigenschappen - uitgezonderd de middelcode - beinvloedt alle kostenposten die het middel toepassen. Bijv. wanneer de materiaalprijs wijzigt zal ook de eenheidsprijs van de kostenpost wijzigen.

               Wijzigen van de middelcode met UMC
               - Bepaal hoeveel kostenposten het middel met de oude middelcode toepassen voor de wijziging (#KTP_OUD)
               - Bepaal hoeveel kostenposten het middel met de nieuwe middelcode toepassen na de wijziging (#KTP_NIEUW).
               - Als #KTP_OUD = 1 en #KTP_NIEUW = 1 dan wijzigt alleen de middelcode van het middel.
               - Als #KTP_OUD = 1 en #KTP_NIEUW > 1 dan moet het oude middel worden verwijderd.
               - Als #KTP_OUD > 1 en #KTP_NIEUW = 1 dan moet een kopie van het oude middel worden gemaakt.
               - Als #KTP_OUD > 1 en #KTP_NIEUW > 1 dan wijzigt alleen de koppeling tussen kostenpost en middel.
               NB als de oude of nieuwe middelcode leeg is dan #KTP_OUD = 1 resp. #KTP_NIEUW = 1

            */

            IBegrotingsRegel? bgrRegel = _Stu[opdracht.StuIndex]._Regel;
            if (bgrRegel?._OnderbouwingType != EOnderbouwing.Kostenpost)
                return false;

            BKostenpost kostenpost = (BKostenpost)bgrRegel;
            BMiddel middelOud = kostenpost._Middel;

            string midcde = opdracht.MidCdeNieuw;
            if (midcde == middelOud._MidCde)
                return false;               // geen wijziging

            opdracht.WijzigDatum = middelOud._WzgDtm;
            opdracht.MidCdeOud = middelOud._MidCde;
            if (!_Umc)                                                   // geen unieke middelencodering?
            {
                // elke kostenpost z'n eigen middel:
                //   dit heeft geen consequenties
                //   voor andere kostenposten
                middelOud.WijzigMiddelCode(midcde);
                opdracht.GeenWijzigDatum = false;                      // tbv UNDO
                kostenpost.MiddelGewijzigd(false);                       // false: geen herberekening nodig
                return true;
            }

            // bepaal of er meer dan 1 kostenpost is
            // die het middel met de huidige code toepast
            opdracht.MeerKtpOud = false;
            opdracht.MiddelOud = middelOud;
            if (string.IsNullOrEmpty(middelOud._MidCde) == false &&
               _Stu.ZoekMiddel(middelOud._Id, kostenpost._Id))
                opdracht.MeerKtpOud = true;

            // bepaal of er al minstens 1 kostenpost is
            // die een middel met de nieuwe code toepast:
            BMiddel? middelNieuw = GeefMiddel(midcde);                                        // Zoek in de begroting zelf
            if (middelNieuw == null)
            {
                // Alleen in het prijzenboek zoeken en een middel overnemen als we een "blanco" code overschrijven
                // Als het een bestaande code is dan betekent dit het wijzigen van de bestaande code van het middel

                if (_Umc && _PrijzenBoek != null && string.IsNullOrEmpty(middelOud._MidCde))
                {
                    middelNieuw = _PrijzenBoek.GeefMiddel(midcde);                            // Zoek in de referentie
                    if (middelNieuw != null)
                    {
                        BMiddel overgenomenMiddel = new BMiddel(GeefNieuwId(), middelNieuw, _VltId); // Maak een nieuw middel op basis van die uit de referentie
                        middelNieuw = overgenomenMiddel;                                        // Dit is het middel welke aan de kostenpost gekoppeld wordt 
                        _Mid.MiddelToevoegen(middelNieuw);
                        if (!_REl._Uln.HeeftUurloon(middelNieuw._UlnCde))                        // Neem indien nodig het uurloon over
                        {
                            UurloonOvernemen(_PrijzenBoek, middelNieuw._UlnCde);
                            opdracht.UurloonToegevoegd = true;
                        }
                    }
                }
            }

            opdracht.MeerKtpNieuw = middelNieuw != null;

            // nu de benodigde wijziging(-en) uitvoeren
            if (opdracht.MeerKtpOud)
            {
                // Meerdere kostenposten passen het middel
                // met de huidige code toe
                if (middelNieuw == null)                                  // Nieuwe code komt nog niet voor (of is leeg)
                {
                    // - Als #KTP_OUD > 1 en #KTP_NIEUW = 1 dan
                    // moet een kopie van het oude middel worden gemaakt.
                    middelNieuw = new BMiddel(GeefNieuwId(), middelOud, middelOud._VltId);
                    middelNieuw.MiddelGewijzigd += MiddelGewijzigd;
                    middelNieuw.WijzigMiddelCode(midcde);

                    kostenpost.WijzigMiddel(middelNieuw, true);            // true: rekenen
                    _Mid.MiddelToevoegen(middelNieuw);
                }
                else                                                     // Nieuwe middelcode wordt reeds toegepast
                {
                    // - Als #KTP_OUD > 1 en #KTP_NIEUW > 1 dan
                    // wijzigt alleen de koppeling tussen
                    // kostenpost en middel.
                    kostenpost.WijzigMiddel(middelNieuw, true);
                    middelNieuw.WijzigingInMiddel();// true: rekenen
                    opdracht._Rekenen = true;
                }
            }
            else
            {
                // Slechts 1 kostenpost die het middel
                // met de huidige code toepast
                if (middelNieuw == null)                                  // Nieuwe code komt nog niet voor (of is leeg)
                {
                    // - Als #KTP_OUD = 1 en #KTP_NIEUW = 1 dan
                    // wijzigt alleen de middelcode van het middel.
                    opdracht.GeenWijzigDatum = false;                   // Tbv UNDO
                    middelOud.WijzigMiddelCode(midcde);
                    kostenpost.MiddelGewijzigd(false);                    // false: geen herberekening nodig
                }
                else                                                     // Nieuwe middelcode wordt reeds toegepast
                {
                    // - Als #KTP_OUD = 1 en #KTP_NIEUW > 1 dan
                    // moet het oude middel worden verwijderd.
                    _Mid.MiddelVerwijderen(middelOud, false);             // false: geen UNDO-actie
                    kostenpost.WijzigMiddel(middelNieuw, true);              // true: rekenen

                    opdracht._Rekenen = true;
                }
                if (middelNieuw != null)
                {
                    middelNieuw.WijzigingInMiddel();
                    middelNieuw.MiddelGewijzigd += MiddelGewijzigd;
                }
                middelOud?.WijzigingInMiddel();

            }
            return true;                                                // De middelcode van de kostenpost is gewijzigd
        }
        public bool Uitvoeren(BWijzigValuta opdracht)
        {
            m_BasisValuta!.BerekenKoersFactoren();
            int vlt = opdracht.GeefValuta(_VltId);
            if (null != m_Stu)
            {
                for (int rglNr = _Stu._Aantal - 1; rglNr >= 0; rglNr--)
                {
                    _Stu.LeesBegrotingsRegel(rglNr);
                    BStructuurRegel stuRegel = _Stu[rglNr];
                    stuRegel._Regel?.WijzigValuta(vlt, m_BasisValuta._ValutaVzl);
                }
            }
            _Mid.WijzigValuta(vlt, opdracht.GeefAlles());
            m_Bbd?.WijzigValuta(vlt);
            BBedrag vstTot = _VstTot;
            if ( /* vstTot._Waarde != 0.0 && */ vstTot.Valuta != vlt)
            {
                vstTot.WijzigValuta(vlt, m_BasisValuta._ValutaVzl);
                _VstTot = vstTot;
            }
            _XtoKst.WijzigValuta(vlt, m_BasisValuta._ValutaVzl);
            //_Vlt = vlt;

            Rekenen(ERekendiepte.Volledig);
            foreach (BValutaDeco valuta in BegrotingsValuta)
            {
                if (valuta._VltId == vlt)
                {
                    m_BasisValuta = (BDocValuta)valuta;
                }
            }
            m_BasisValuta.BerekenKoersFactoren();
            Rekenen(ERekendiepte.Volledig);
            return true;
        }

