        public void MeetstaatKopieenVerwijderen(BMeetstaatKopieRegistratie? meetstaatKopieRegistratie)
        {
            if (meetstaatKopieRegistratie != null)
            {
                // Verwijder koppelingen
                int index = 0;
                int id = meetstaatKopieRegistratie.GeefKoppelingIdKopie(ref index);
                while (id != 0)
                {
                    VerwijderMeetstaatKoppeling(id, out BMeetstaatKoppeling? _, out BewaarItemMutatieStatus _);
                    id = meetstaatKopieRegistratie.GeefKoppelingIdKopie(ref index);
                }

                // Verwijder meetstaten
                index = 0;
                id = meetstaatKopieRegistratie.GeefMeetstaatIdKopie(ref index);
                while (id != 0)
                {
                    VerwijderMeetstaat(id);
                    id = meetstaatKopieRegistratie.GeefMeetstaatIdKopie(ref index);
                }

                // Verwijder meetstaatmodellen
                index = 0;
                id = meetstaatKopieRegistratie.GeefMeetstaatModelIdKopie(ref index);
                while (id != 0)
                {
                    _MeetstaatModelVzl.VerwijderModel(id);
                    id = meetstaatKopieRegistratie.GeefMeetstaatModelIdKopie(ref index);
                }
                VerhoogMeetstaatVersie();
            }
        }
