        public BStructuurRegel MaakKostenpost(int elementId)
        {
            Debug.Assert(_Stu._Aantal > 0 && _Stu[0]._Regel != null, "Geen rootelement aanwezig in begrotingsstructuur");

            // Nieuwe kostenpost aanmaken met standaarduurloon en zonder verzamelpost
            var kostenpost = new BKostenpost(GeefNieuwId(), string.Empty, _VltId, this);

            // Nieuw middel aanmaken, aan kostenpost koppelen en in de middelenlijst opnemen
            var middel = new BMiddel(GeefNieuwId(), _VltId);
            middel.MiddelGewijzigd += MiddelGewijzigd;
            kostenpost.WijzigMiddel(middel, false);    // rekenen is niet nodig want _Hvh == 0.0

            _Mid.MiddelToevoegen(middel);

            if (_ibisConfiguration?.Functions?.CreateBewakingscodeFromElement?.Value ?? false == true)
            {
                bool gegevensAanvullen = false;
                switch (m_ActieContext)
                {
                    case EActieContext.ToevoegenRegelEronder:
                    case EActieContext.ToevoegenRegelErvoor:
                    case EActieContext.ToevoegenRegelNaEnter:
                        gegevensAanvullen = true;
                        break;
                }
                if (gegevensAanvullen)
                {
                    int elementIndex = _Stu.ZoekElement(elementId);
                    if (elementIndex > 0)
                    {
                        if (_Stu[elementIndex]._Regel is BElement element)
                        {
                            kostenpost._BwcArb = element._BwcArb;
                            kostenpost._BwcMta = element._BwcMta;
                            kostenpost._BwcMte = element._BwcMte;
                            kostenpost._BwcOda = element._BwcOda;
                        }
                    }
                }
            }

            // Wijzigingen in de structuur opnemen
            var stuRegel = new BStructuurRegel(kostenpost, elementId);
            return stuRegel;
        }

