                s_VoorbeeldBegroting = bgr;
                kostenpost?.WijzigUurloon(ulnCde);
                bgr.RegistreerOpdrachten(true);   // houdt in: bgr.Rekenen(ERekendiepte.Volledig);
            }
            return s_VoorbeeldBegroting;
