        public bool HeeftLegeElementCodes(BBegrotingsRegel.EGegeven codeKolom)
        {
            string? orgDoc = _logboek.Document;
            bool legeElementCodes = false;

            try
            {
                _logboek.Document = _DocumentNaam;

                for (int stuIndex = 1; stuIndex < _Stu._Aantal; stuIndex++) // root doet niet mee
                {
                    BStructuurRegel stuRegel;
                    if (_Stu[stuIndex]._Tpe == EOnderbouwing.Element)
                    {
                        stuRegel = _Stu[stuIndex];
                        if (stuRegel._Regel == null)
                            _Stu.LeesBegrotingsRegel(stuIndex);

                        string code = stuRegel._Regel!.GeefString(codeKolom, true);
                        if (string.IsNullOrEmpty(code))
                        {
                            legeElementCodes = true;
                            _logboek.Toevoegen(_DocumentNaam, stuIndex, ProjectResources.TradB2413);
