        {
            Debug.Assert(m_Stu != null, "BBegroting.VerplaatsBegrotingsRegelsSequentieel() - geen structuurlijst");
            Debug.Assert(eltId > 0 || (newStartIndex > 0 && newStartIndex <= _Stu._Aantal), "BBegroting.VerplaatsBegrotingsRegels() - doel-index of element-ID verkeerd");

            var opdracht = new VerplaatsBegrotingRegelsSequentieelOpdracht(this, startIndex, count, newStartIndex);

