        /// <summary>
        /// Maak een commentaarregel aan en voeg hem toe aan de structuur van de begroting
        /// NB Dit is bedoeld voor conversie van TRAD-5 begrotingen
        /// </summary>
        /// <param name="elementId">ID van het parentelement</param>
        /// <param name="eindeBegroting">true: laatste regel van de begroting, false: laatste regel van de elementonderbouwing</param>
        /// <returns>De nieuwe commentaarregel</returns>
        public BCommentaar? MaakCommentaar(int elementId, bool eindeBegroting)
        {
            // Nieuw commentaar aanmaken
            BStructuurRegel stuRegel = MaakCommentaar(elementId);
            if (eindeBegroting)
                _Stu.Toevoegen(stuRegel);
            else
                _Stu.Invoegen(stuRegel, elementId, -1);  // -1: invoegpositie is einde vh element
            return stuRegel._Regel as BCommentaar;
        }
        public BStructuurRegel MaakCommentaar(int elementId)
        {
