        public bool ControleerBgrDubbeleMsk()
        {
            if (_MeetstaatKoppelingen._Aantal == 0)
                return false;

            int mskDocumentId_1, mskDocumentId_2;
            int stuIndex;

            for (int mskIndex_1 = _MeetstaatKoppelingen._Aantal - 1; mskIndex_1 >= 0; mskIndex_1--)
            {
                mskDocumentId_1 = _MeetstaatKoppelingen[mskIndex_1]._DocumentId;
                if (mskDocumentId_1 <= 0)
                    continue;

                stuIndex = _Stu.ZoekId(mskDocumentId_1);
                if (stuIndex <= 0)
                    continue;

                for (int mskIndex_2 = mskIndex_1 - 1; mskIndex_2 >= 0; mskIndex_2--)
                {
                    mskDocumentId_2 = _MeetstaatKoppelingen[mskIndex_2]._DocumentId;

                    if (mskDocumentId_1 == mskDocumentId_2)
                        return true;
                }
            }

            return false;
        }

        public BBegrotingsRegel.EBegrotingConsistentieStatus ControleerBgrRegelMeetstaatkoppeling()
        {
            BMeetstaatKoppeling msk;
            int stuIndex;
            IBegrotingsRegel? begrotingsRegel;
            double hvhBgr;

            for (int mskIndex = _MeetstaatKoppelingen._Aantal - 1; mskIndex >= 0; mskIndex--)
            {
                msk = _MeetstaatKoppelingen[mskIndex];
                if (msk._DocumentId <= 0)
                    continue;

                stuIndex = _Stu.ZoekId(msk._DocumentId);
                if (stuIndex <= 0)
                    return BBegrotingsRegel.EBegrotingConsistentieStatus.LozeMsk;

                _Stu.LeesBegrotingsRegel(stuIndex);
                begrotingsRegel = _Stu[stuIndex]._Regel;
                if (begrotingsRegel?._MstKid != msk._KoppelingId)
                {
                    if (begrotingsRegel?._MstKid == -msk._KoppelingId)
                        continue;

                    return BBegrotingsRegel.EBegrotingConsistentieStatus.BgrMstKid;
                }

                BMeetstaat? meetstaat = GeefMeetstaat(begrotingsRegel, out BMeetstaatKoppeling? meetstaatKoppeling);
                if (meetstaatKoppeling == null || meetstaat == null)
                    return BBegrotingsRegel.EBegrotingConsistentieStatus.GeenMst;

                hvhBgr = begrotingsRegel.GeefDouble(BBegrotingsRegel.EGegeven.hvh, out bool geenWaardeBgr);
                if (geenWaardeBgr)
                    continue;

                double hvhMst = meetstaat.GeefGekoppeldeWaarde(meetstaatKoppeling, out bool geenWaardeMst);
                if (geenWaardeMst)
                    continue;

                if (!_statics.GetallenZijnGelijk(hvhBgr, hvhMst, 3))
                    return BBegrotingsRegel.EBegrotingConsistentieStatus.BgrHvh;
            }

            return BBegrotingsRegel.EBegrotingConsistentieStatus.Ok;
        }

        public void ControleerStructuur(EBegrotingControleStap begrotingControleStappen)
        {
            LogboekMelding(ProjectResources.TradA002412725);

            // Run 1 Controleer _MaxId
            // Run 2 Alle regel die geen juiste parent hebben
            // Run 4 Alle kostenposten/commentaar die ook als elem/comm voorkomen
            // Run 3 Ontbrekende middelen
            // Run 5 Alle elementen die ook als element voorkomen
            // Run 6 Alle regels die een parent id hebben welke geen element is
            // Run 7 Alle regels op hierarchie
            // Run 8 Alle regels op meetstaat
            try
            {
                _structuurStatusFout.BegrotingControleStappen = begrotingControleStappen;

                _Stu.GeefNiveau(0);
                _logboek.Toevoegen(_Naam, ProjectResources.TradA002412726);//i.v.m multiple gebruik functie
                _Stu.ControleerLosseNietElementen(this); //LosseKtpMidden = 512,

                //ControleerMaxId();         //  1 Run 1 Controleer _MaxId
                ControleerParents();       //  2 Run 2 Alle regel die geen juiste parent hebben
                ControleerKpComId();       //  4 Run 4 Alle kostenposten/commentaar die ook als elem/comm voorkomen
                ControleerMiddelen();      //  8 Run 3 Ontbrekende middelen
                ControleerElement();       // 16 Run 5 Alle elementen die ook als element voorkomen

                if (_structuurStatusFout.ControleerBegrotingStatus == EControleerBegrotingStatus.Controleren)
                {
                    ControleerParentType();    // 32 Run 6 Alle regels die een parent id hebben welke geen element is
