        public BOpdracht? WijzigStringBgrRegel(bool klassiek, int stuIndex, BBegrotingsRegel.EGegeven gegevenNr, string waarde, IOpdrachtValidator? opdrachtValidator, out bool lokaal)
        {
            BOpdracht? opdracht = null;
            lokaal = true;
            IBegrotingsRegel? bgrRegel = _Stu[stuIndex]._Regel;
            if (bgrRegel == null)
                return null;
            BKostenpost? ktp = bgrRegel as BKostenpost;

            if (gegevenNr == BBegrotingsRegel.EGegeven.stk)
            {
                bool nieuweGroepeerOpdrachtGemaakt = GroepeerOpdrachten(); // Er is een mogelijkheid dat bij deze wijzigingen groepsopdrachten gemaakt worden

                if (waarde == BBegrotingsRegel.c_sAlleenOmsHoev || waarde == BBegrotingsRegel.c_sAlleenTotPrys || waarde == BBegrotingsRegel.c_sNietafdrukken)
                {
                    string stk = bgrRegel.GeefString(BBegrotingsRegel.EGegeven.stk, klassiek);

                    if (string.IsNullOrEmpty(stk) == false && stk != BBegrotingsRegel.c_sAlleenOmsHoev && stk != BBegrotingsRegel.c_sAlleenTotPrys)
                    {
                        WijzigStringBgrRegel(bgrRegel, klassiek, stuIndex, gegevenNr, string.Empty, opdrachtValidator, out lokaal);
                        lokaal = false;
                        // Het type van de regel kan gewijzigd zijn >> opnieuw bepalen
                        bgrRegel = _Stu[stuIndex]._Regel;
                    }

                    WijzigStringBgrRegel(bgrRegel, klassiek, stuIndex, gegevenNr, waarde, opdrachtValidator, out lokaal);
                }
                else if (bgrRegel.HeeftStatus(ERegelStatus.KtpCommentaar) && bgrRegel._OnderbouwingType != EOnderbouwing.Opslagpost)  // ".,-"
                {
                    int statusOud = bgrRegel._Stt;
                    bgrRegel.WijzigRegelStatus(ERegelStatus.Normaal);
                    // Als een punt of komma stuurcode vervangen wordt door een spatie of lege string dan alle
                    // statussen weer op 0 zetten (ook niet meerekenen)
                    bool isLetter = false;
                    if (waarde.Length > 0)
                        isLetter = (ktp != null) && Char.IsLetter(waarde, 0);
                    if (string.IsNullOrEmpty(waarde) || waarde == BStatics.c_Spatie || isLetter || waarde == "?")//NIETVERTALEN
                        bgrRegel._Actief = true;
                    int statusNieuw = bgrRegel._Stt;
                    opdracht = new BWijzigStatusBgrRegel(stuIndex, statusOud, statusNieuw, true);
                    if (opdracht != null)
                    {
                        opdracht.SetView(_ViewNr);
                        if (opdracht != null)
                            _OpdrachtVzl.Aanmelden(opdracht);
                    }
                    WijzigStringBgrRegel(bgrRegel, klassiek, stuIndex, gegevenNr, waarde, opdrachtValidator, out lokaal);
                    lokaal = false; // tgv de wijziging in status moet deze op false gezet worden
                    BgrRglGewijzigd(bgrRegel, true);
                }
                else
                {
                    WijzigStringBgrRegel(bgrRegel, klassiek, stuIndex, gegevenNr, waarde, opdrachtValidator, out lokaal);
                }
                // Als er een nieuwe groepeerOpdracht gemaakt is dan deze nu afsluiten
                // Als er al een groepeeropdracht was dan worden de opdrachten automatisch aangemeld bij die groepeeropdracht
                if (nieuweGroepeerOpdrachtGemaakt)
                {
                    opdracht = GroepeerOpdrachten(_ViewNr, ProjectResources.TradB24226);

                    if (opdracht != null)//bug 4273
                    {
                        opdracht._RegelNummer = stuIndex;//comm Js de stuindex blijft hetzelfde
                        _Context = opdracht._Context;
                    }
                }
                return opdracht;
            }
            else if (gegevenNr == BBegrotingsRegel.EGegeven.OnderhoudsCode)
            {
                bool nieuweGroepeerOpdrachtGemaakt = GroepeerOpdrachten(); // Er is een mogelijkheid dat bij deze wijigingen groepsopdrachten gemaakt worden

                WijzigStringBgrRegel(bgrRegel, klassiek, stuIndex, gegevenNr, waarde, opdrachtValidator, out lokaal);
                if (_BrinkKostenbestandEigenschappenOnderhoud?._MJOBActiefBerekenen == true)
                {
                    // Direct de regel berekenen.
                    RekenenMjobContanteWaardeInvestering(bgrRegel);
                }
                else
                {
                    // Parameter op false zetten.
                    _MjobContanteWaardeIsActueel = false;
                }

                if (nieuweGroepeerOpdrachtGemaakt)
                {
                    opdracht = GroepeerOpdrachten(_ViewNr, ProjectResources.TradB24227);

                    if (opdracht != null)
                    {
                        opdracht._RegelNummer = stuIndex;//comm Js de stuindex blijft hetzelfde
                        _Context = opdracht._Context;
                    }
                }
                return opdracht;
            }
            else
            {
                return WijzigStringBgrRegel(bgrRegel, klassiek, stuIndex, gegevenNr, waarde, opdrachtValidator, out lokaal);
            }
        }


        public BOpdracht? WijzigStringBgrRegel(IBegrotingsRegel? bgrRegel, bool klassiek, int stuIndex, BBegrotingsRegel.EGegeven gegevenNr, string waarde, IOpdrachtValidator? opdrachtValidator, out bool lokaal)
        {
            lokaal = true;

            BOpdracht? opdracht = bgrRegel?.MaakWijzigStringOpdracht(klassiek, stuIndex, gegevenNr, waarde);
            if (opdracht == null)
                return null;

            if (opdracht is BVerhoogNiveauBgrRegel verhoogNiveauOpdracht)
                verhoogNiveauOpdracht.VerhoogNiveau = _optieNiveauWisseling.IsMeedegraderenGewenst();

            if (opdrachtValidator != null && !opdrachtValidator.ValideerOpdracht(opdracht))
                return null;

            if (!opdracht.Uitvoeren(this))
                return null;

            if (opdracht._Hertekenen != EHertekenen.Lokaal)
                lokaal = false;

            if (!m_Snel)
            {
                if (opdracht._Rekenen)
                    Rekenen(ERekendiepte.Wijzigingen);

                _OpdrachtVzl.Aanmelden(opdracht);
            }
            opdracht._RegelNummer = stuIndex;
            _Context = opdracht._Context;

            return opdracht;
        }

