        /// <returns>Het nieuwe element</returns>
        public BElement MaakElement(int parentId, bool eindeBegroting)
        {
            BStructuurRegel stuRegel = MaakElement(parentId);
            if (eindeBegroting)
                _Stu.Toevoegen(stuRegel);
            else
                _Stu.Invoegen(stuRegel, parentId, -1);  // -1: invoegpositie is einde vh element
            return (BElement)stuRegel._Regel!;
        }
        public BStructuurRegel MaakElement(int parentId)
