        /// <param name="opdracht">Opdrachtobject met gegevens die nodig zijn om een aantal regels te kopi?ren</param>
        public bool PlakBegrotingsRegels(BPlakBgrRegels opdracht)
        {
            if (opdracht == null) return false;

            BPlakBgrRegelsUMCRef? umcRefOpdracht = opdracht as BPlakBgrRegelsUMCRef;
            if (umcRefOpdracht != null)
            {
                if (!Uitvoeren(umcRefOpdracht))
                    return false;
            }
            else
            {
                if (!Uitvoeren(opdracht))
                    return false;
            }

            _Context = opdracht._Context;
            if (!m_Snel)
            {
                if (opdracht._Rekenen)
                    Rekenen(ERekendiepte.Wijzigingen);
                if (umcRefOpdracht != null)
                    _OpdrachtVzl.Aanmelden(umcRefOpdracht);
                else
                    _OpdrachtVzl.Aanmelden(opdracht);
            }

            return true;
        }

