        public double GeefCumulatieveHvh(int middelId)
        {
            double cumulatieveHvh = 0.0;
            int stuIndex = -1;
            IStructuur bgrStructuur = _Stu;
            BKostenpost? kostenpost = (BKostenpost?)bgrStructuur.GeefVolgendeBgrRegel(EOnderbouwing.Kostenpost, ref stuIndex);
            while (kostenpost != null)
            {
                if (kostenpost._Actief && kostenpost._Middel._Id == middelId)
                {
                    if (kostenpost._Dri != EDri.Tgd)
                        cumulatieveHvh += kostenpost._DrkHvh;
                    else
                        cumulatieveHvh += 1.0;
                }
                kostenpost = (BKostenpost?)bgrStructuur.GeefVolgendeBgrRegel(EOnderbouwing.Kostenpost, ref stuIndex);
            }
            return cumulatieveHvh;
        }

        public void BepaalMiddelenGebruik(int middelId, BMiddelenGebruik middelenGebruik)
        {
            IStructuur structuur = _Stu;
            BElement element = _REl;
            BKostenpost kostenpost;

            // Doorloop de onderbouwing
            int aantalRegels = structuur._Aantal;
            IBegrotingsRegel? bgrRegel;
            for (int stuIndex = 0; stuIndex < aantalRegels; stuIndex++)
            {
                bgrRegel = structuur[stuIndex]._Regel;
                switch (bgrRegel?._OnderbouwingType)
                {
                    case EOnderbouwing.Element:  // subelement 
                        element = (BElement)bgrRegel;
                        break;

                    case EOnderbouwing.Kostenpost:
                        kostenpost = (BKostenpost)bgrRegel;
                        if (kostenpost._Middel._Id == middelId)
                            middelenGebruik.KostenpostToevoegen(kostenpost, element, stuIndex);   // Ook als de kostenpost niet actief is
                        break;
                }
            }
            middelenGebruik.SelecteerMiddel(middelId, null);
        }

