        public void MaakBrutoBegroting(BgrOpslaan bgrOpslaan, bool alleBtwRegels)
        {
            Debug.Assert(m_Bbd != null, "BBegroting.MaakBrutoBegroting() - Er is nog geen begrotingsblad in het BBegroting-object");
            Rekenen(ERekendiepte.Volledig);
            double totaalBegroting = _BgrBto.Waarde;
            IBegroting ibrutobegroting = _maakBrutobegroting.MaakBrutoBegroting(bgrOpslaan, alleBtwRegels, this);
            // Zorg ervoor dat de opdrachten verzameling leeg is na het omzetten naar bruto begroting
            ibrutobegroting.OpdrachtenVergeten();

            _OpdrachtVzl.Gewijzigd();
            ThrowExceptionAlsTotaalOorspronkelijkeBegrotingEnBrutobegrotingVerschilt(totaalBegroting, ibrutobegroting);
        }

        private static void ThrowExceptionAlsTotaalOorspronkelijkeBegrotingEnBrutobegrotingVerschilt(double totaalBegroting, IBegroting ibrutobegroting)
        {
            const double toegestaanVerschilBegrotingsposten = 1d;  // Er mag een klein verschil zijn tussen de oorspronkelijke begroting en de brutobegroting, vanwege afrondingen
            const double toegestaanVerschil = 10d;   // Groter verschil wordt toegelaten

            double totaalBrutoBegroting = ibrutobegroting._BgrBto.Waarde;
            double absVerschil = Math.Abs(totaalBrutoBegroting - totaalBegroting);
            double margeAfrondingsVerschil = ibrutobegroting.BegrotingspostenToepassen ? toegestaanVerschilBegrotingsposten : toegestaanVerschil;
            if (absVerschil >= margeAfrondingsVerschil)
            {
                throw new TotaalOorspronkelijkeBegrotingEnBrutobegrotingVerschiltException();
            }
        }

