        #region Constructor
        public BBegroting(string naam, BDocValuta basisValuta, IMaxIdBepaler maxIdBepaler)
        {
            _DocumentNaam = string.IsNullOrWhiteSpace(naam)
                ? $"{ProjectResources.TradC1172511512714}{BStatics.c_Spatie}{++m_NaamNummer}"
                : naam.SaneerTekst();

            Debug.Assert(basisValuta._ValutaVzl != null, "basisValuta._ValutaVzl is null");
            Debug.Assert(basisValuta._ValutaVzl[0] == basisValuta, "basisValuta._ValutaVzl[0] is niet basisValuta");

            BegrotingsValuta = basisValuta._ValutaVzl;
            m_BasisValuta = basisValuta;
            _maxIdBepaler = maxIdBepaler;

            NieuweBegroting();
        }

        public BBegroting(string naam, EBgrTpe tpe, double totuur, string dtm, BXtoKst xtokst, BDocValuta basisValuta, IMaxIdBepaler maxIdBepaler)
        {
            _DocumentNaam = naam.SaneerTekst();

            Debug.Assert(BegrotingsValuta == null, "BBegroting de ValutaVzl mag niet op deze manier gewijzigd worden");
            Debug.Assert(basisValuta._ValutaVzl != null, "_ValutaVzl is null mag niet toegekend worden");

            BegrotingsValuta = basisValuta._ValutaVzl;
            _maxIdBepaler = maxIdBepaler;

            Debug.Assert(m_BasisValuta == null, "BBegroting de basisvaluta mag niet op deze manier gewijzigd worden");
            Debug.Assert(basisValuta != null, "basisValuta is null mag niet toegekend worden");

            m_BasisValuta = basisValuta;
            ZetBegrotingType(tpe);
            m_TotUur = totuur;
            m_Dtm = dtm;
            m_XtoKst = xtokst;

            m_Mid = new BMiddelen(this);
            m_Bgv = new BBegrotingsGegevenVzl();
            m_Ggv = new BGebruikersGegevenVzl();

            m_RawInfo = new BRawInfo(m_Bgv);
            m_RawInfo.ZetRawBegroting(m_Tpe == EBgrTpe.Raw);
            _OpdrachtVzl = new BOpdrachtVzl(this, 0);

            m_Umc = -1;            // -1: onbepaald, moet nog worden opgezocht in m_Bgv
        }

        public void Instellen(string naam, EBgrTpe tpe, double totuur, string dtm, BXtoKst xtokst, BDocValuta basisValuta)
        {
            _DocumentNaam = naam.SaneerTekst();
            ZetBegrotingType(tpe);
            m_TotUur = totuur;
            m_Dtm = dtm;
            m_XtoKst = xtokst;

            InstellenBasisValuta(basisValuta);
        }

        private void InstellenBasisValuta(BDocValuta basisValuta)
        {
            if (basisValuta == null || BegrotingsValuta.Count == 0)
                return;

            m_BasisValuta = ((BDocValuta)BegrotingsValuta[0]).GeefValutaDeco(basisValuta._Aanduiding, false) as BDocValuta;
        }

        public IBegroting KopierenExclusiefRegels()
        {
            BBegroting orig = this;

            BDocValuta docValuta = BDocValuta.MaakValuta(orig.BegrotingsValuta, orig._BasisValuta?._VltId ?? 0, orig._BasisValuta?._Aanduiding, orig._BasisValuta?._Koers ?? 0, orig._BasisValuta?._Omschrijving, orig._BasisValuta?._Teken, orig._BasisValuta?._Datum ?? default);
            foreach (BValutaDeco valuta in docValuta._ValutaVzl)
            {
                valuta.ZetMutatieStatus(BewaarItemMutatieStatus.Nieuw);
            }

            BBegroting kopie = new BBegroting(orig._DocumentNaam, orig.m_Tpe, orig.m_TotUur, _statics.GeefHuidigeTijd(),
                new BXtoKst(orig._VltId, docValuta._ValutaVzl), docValuta, new BegrotingMaxIdBepaler());
            kopie.m_Oms = orig.m_Oms;
            kopie.m_Umc = orig.m_Umc;

            kopie._Bbd = new BBegrotingBlad(kopie, orig._Bbd);
            kopie._OpdrachtVzl = new BOpdrachtVzl(kopie, 0);
            kopie.m_Bgv = new BBegrotingsGegevenVzl(orig.m_Bgv);
            kopie.m_Ggv = new BGebruikersGegevenVzl(orig.m_Ggv);
            kopie.m_Stu = new BStructuur(kopie);
            kopie.VasttotaalId = 0;    // Nog geen sjoemelpost aangewezen

            // Rootelement aanmaken:
            BElement rootEl = new(c_RElId, kopie._VltId, kopie);
            rootEl.WijzigHoeveelheid(1.0);
            rootEl.WijzigString(BBegrotingsRegel.EGegeven.oms, orig._REl._Oms, out _);
            BStructuurRegel stuRegel = new BStructuurRegel(rootEl, 0);
            kopie._Stu.Toevoegen(stuRegel);

            // Standaard uurloon overnemen
            BUurloonBVzl ulnVzlOrig = (BUurloonBVzl)orig._REl._Uln;
            BUurloonBVzl ulnVzl = (BUurloonBVzl)rootEl._Uln;
            ulnVzl.KopieerUurlonen(ulnVzlOrig, docValuta._ValutaVzl);

            return kopie;
        }

        /// <summary>
        /// Bij het aanmaken van een nieuwe begroting wordt valutaID op default gezet. 
        /// Deze functie zet valuta op de gewenste waarde
        /// </summary>
        /// <param name="vltid">ID van de gewenste begrotingvaluta</param>
        private void ZetValuta(int vltid)
        {
            m_XtoKst = new BXtoKst(vltid, BegrotingsValuta);
            _REl.ZetValuta(vltid, BegrotingsValuta);
        }
        private void NieuweBegroting()
        {
            m_XtoKst = new BXtoKst(_VltId, BegrotingsValuta);
            m_Tpe = EBgrTpe.Traditioneel;
            m_Dtm = _statics.GeefHuidigeTijd();
            m_Oms = string.Empty;

            // Structuur aanmaken - komt nu niet uit de database
            m_Stu = new BStructuur(this);

            // Rootelement aanmaken:
            BElement rootEl = new BElement(c_RElId, _VltId, this);
            rootEl.WijzigHoeveelheid(1.0);
