        /// <summary>
        /// Wijzig het onderbouwingstype van een begrotingsregel
        /// </summary>
        /// <param name="stuIndex">Index van structuurelement behorend bij de begrotingsregel</param>
        /// <param name="naarType">Het nieuwe onderbouwingstype</param>
        /// <param name="klassiek">Bepaalt wat er met de onderbouwing moet gebeuren als het huidige onderbouwingstype element is</param>
        /// <returns>true indien het onderbouwingstype is gewijzigd</returns>
        public BOpdracht? OmzettenBegrotingsRegel(int stuIndex, EOnderbouwing naarType, bool klassiek)
        {
            Debug.Assert(m_Stu != null, "Geen structuurlijst in de begroting");
            Debug.Assert(stuIndex >= 0, "Verkeerde structuurlijstindex: te laag");
            Debug.Assert(stuIndex < _Stu._Aantal, "Verkeerde structuurlijstindex: te hoog");

            if (stuIndex <= 0)  // rootelement mag niet worden omgezet
                return null;

            OmzettenBegrotingRegelOpdracht opdracht = new OmzettenBegrotingRegelOpdracht(this, stuIndex, klassiek, naarType, string.Empty);

            if (!opdracht.Uitvoeren(null))
                return null;
            _Context = opdracht._Context;

            if (!m_Snel)
            {
                if (opdracht._Rekenen)
                    Rekenen(ERekendiepte.Wijzigingen);

                _OpdrachtVzl.Aanmelden(opdracht);
            }
            return opdracht;
        }
        /// <summary>
        /// Verplaats een regel in de onderbouwing van een element
        /// </summary>
        /// <param name="stuIndex">Index in de structuurlijst van de begrotingsregel die verplaatst moet worden</param>
        /// <param name="naarVoren">true: verplaats de regel naar voren - indien mogelijk</param>
        /// <returns>true indien er een verplaatsing heeft plaatsgevonden</returns>
        public bool VerplaatsOnderbouwing(int stuIndex, bool naarVoren, EViewKey viewNr, bool alsElement)
        {
            int stuIndexDoel;
            int startIndex;
            int count;
            // Bepaal welke regels verplaatst moeten worden en
            // waarheen de selectie verplaatst moet worden
            if (naarVoren)
            {
                int eindeSelectie = _Stu.EindeOnderbouwing(stuIndex) + 1;
                startIndex = stuIndex;
                count = eindeSelectie-startIndex;
                if (alsElement)
                {
                    if (!_Stu.GeefVorigSubElement(stuIndex, out stuIndexDoel))
                        return false;
                }
                else
                {
                    if (!_Stu.GeefVorigeOnderbouwing(stuIndex, out stuIndexDoel))
                        return false;
                }
            }
            else
            {
                int bStuIndex;
                if (alsElement)
                {
                    if (!_Stu.GeefVolgendSubElement(stuIndex, out bStuIndex))
                        return false;
                }
                else
                {
                    if (!_Stu.GeefVolgendeOnderbouwing(stuIndex, out bStuIndex))
                        return false;
                }

                int eindeSelectie = _Stu.EindeOnderbouwing(bStuIndex) + 1;
                startIndex = bStuIndex;
                count = eindeSelectie - startIndex;
                stuIndexDoel = stuIndex;
            }
            int prtId = _Stu[stuIndex]._PrtId;

            // Geef opdracht tot verplaatsing door VerplaatsBegrotingsRegelsSequentieel // bug 3592
            BOpdracht? opdracht = VerplaatsBegrotingsRegelsSequentieel(startIndex, count, stuIndexDoel, prtId);
            if (opdracht == null)
                return false;

            _Context = opdracht._Context;
            opdracht.SetView(viewNr);
            return true;
        }
        /// <summary>
        /// Verplaats een of meerdere begrotingsregels
        /// </summary>
        /// <param name="selectie">De (evt. discontinue) selectie van begrotingsregels in het origineel</param>
        /// <param name="stuIndexDoel">De bestemming van de regels die verplaatst moeten worden</param>
        /// <param name="eltId">ID van het element waarheen de regels verplaatst moeten worden</param>
        /// <returns>true indien er een verplaatsing heeft plaatsgevonden</returns>
        public BOpdracht? VerplaatsBegrotingsRegels(BSelectie selectieOrig, int stuIndexDoel, int eltId)
        {
            Debug.Assert(m_Stu != null, "BBegroting.VerplaatsBegrotingsRegels() - geen structuurlijst");
            //Debug.Assert(eltId > 0 || (stuIndexDoel > 0 && stuIndexDoel <= _Stu._Aantal), "BBegroting.VerplaatsBegrotingsRegels() - doel-index of element-ID verkeerd");

            VerplaatsBegrotingRegelsOpdracht opdracht = new VerplaatsBegrotingRegelsOpdracht(this, selectieOrig);

            //BBegrotingSelectie bs = new BBegrotingSelectie(this, selectieOrig);
            //BPlakBgrRegels opdracht = new BPlakBgrRegels(bs);
            opdracht.StuIndexDoel = stuIndexDoel;
            opdracht.PrtIdDoel = eltId;


            if (!opdracht.Uitvoeren(null!))
                return null;
            _Context = opdracht._Context;
            if (!m_Snel)
            {
                if (opdracht._Rekenen)
                    Rekenen(ERekendiepte.Wijzigingen);

                _OpdrachtVzl.Aanmelden(opdracht);
            }

            return opdracht;
        }
        /// <summary>
        /// Verplaats een of meerdere begrotingsregels sequentieel t.b.v bewerkingen
        /// Let op! Dit is niet de functie verplaatsen van de regel met drag in de begroting
        /// </summary>
        /// <param name="selectie">De (evt. discontinue) selectie van begrotingsregels in het origineel</param>
        /// <param name="stuIndexDoel">De bestemming van de regels die verplaatst moeten worden</param>
        /// <param name="eltId">ID van het element waarheen de regels verplaatst moeten worden</param>
        /// <returns>true indien er een verplaatsing heeft plaatsgevonden</returns>
        public BOpdracht? VerplaatsBegrotingsRegelsSequentieel(int startIndex, int count, int newStartIndex, int eltId)
        {
            Debug.Assert(m_Stu != null, "BBegroting.VerplaatsBegrotingsRegelsSequentieel() - geen structuurlijst");
            Debug.Assert(eltId > 0 || (newStartIndex > 0 && newStartIndex <= _Stu._Aantal), "BBegroting.VerplaatsBegrotingsRegels() - doel-index of element-ID verkeerd");

            var opdracht = new VerplaatsBegrotingRegelsSequentieelOpdracht(this, startIndex, count, newStartIndex);

            //BBegrotingSelectie bs = new BBegrotingSelectie(this, selectieOrig);
            //BPlakBgrRegels opdracht = new BPlakBgrRegels(bs);
            opdracht.PrtIdDoel = eltId;
            if (!opdracht.Uitvoeren(null!)) return null;
            _Context = opdracht._Context;

            _Stu._VolgordeOfHierarchieWijziging = true;

            if (!m_Snel)
            {
                if (opdracht._Rekenen)
                    Rekenen(ERekendiepte.Wijzigingen);

                _OpdrachtVzl.Aanmelden(opdracht);
            }
            return opdracht;
        }

