                onderhoudsGegevens = _rapportService.RapportDataLezen(rptid, null, MjobRapport.TypeOnderhoud);

            }

            return onderhoudsGegevens;
        }

        private static string GenereerXmlTekst(List<BStructuurRegel> regels, BBegrotingsRegel.EGegeven onderhoudsCodeKolom)
        {
            using MemoryStream ms = new MemoryStream();
            using XmlTextWriter w = new XmlTextWriter(ms, Encoding.GetEncoding("utf-16"));//NIETVERTALEN
            w.Formatting = Formatting.Indented;

            w.WriteStartDocument();
            w.WriteStartElement("onderhoudsxml");//NIETVERTALEN
            foreach (BStructuurRegel item in regels)
            {

                int niv = item._Niveau;
                string? code = item._Regel?.GeefString(BBegrotingsRegel.EGegeven.cclcde, false);
                string? oms = item._Regel?.GeefString(BBegrotingsRegel.EGegeven.oms, false);
                w.WriteStartElement("ond");//NIETVERTALEN
                w.WriteAttributeString("niv", XmlConvert.ToString(niv));//NIETVERTALEN
                w.WriteAttributeString("rglnr", XmlConvert.ToString(item._Id)); //NIETVERTALEN // Geeft de regel_id in de begroting aan (is niet de stuIndex)
                w.WriteAttributeString("code", code);//NIETVERTALEN
                w.WriteAttributeString("oms", oms);//NIETVERTALEN

                string ondcode = item._Regel?.GeefString(onderhoudsCodeKolom, false)?.Trim() ?? string.Empty;  // Lees de onderhoudscode
                if (!string.IsNullOrEmpty(ondcode))
                {
                    bool geenWaarde = false;
                    double hvh = item._Regel is { } r ? r.GeefDouble(BBegrotingsRegel.EGegeven.drkhvh, out geenWaarde) : 0;
                    string enh = item._Regel?.GeefString(BBegrotingsRegel.EGegeven.enh, false) ?? string.Empty;

                    w.WriteAttributeString("ondcode", ondcode);//NIETVERTALEN
                    w.WriteAttributeString("hvh", XmlConvert.ToString((decimal)hvh));//NIETVERTALEN
                    w.WriteAttributeString("enh", enh);//NIETVERTALEN
                }
                w.WriteEndElement();
            }
            w.WriteEndElement();
            w.WriteEndDocument();
            w.Flush();
            ms.Position = 0;
            using StreamReader reader = new StreamReader(ms);
            return reader.ReadToEnd();
        }

        /// <summary>Genereer een nieuw uurloon op basis van een bestaand uurloon
        /// </summary>
        /// <param name="uurloonCodeOrg"></param>
        /// <param name="uurloonVzl"></param>
        /// <returns></returns>
        public string GeefUniekeUurloonCode(string uurloonCodeOrg, BUurloonCVzl uurloonVzl, string prefix)
        {
            string? uurloonCode = null;
            // Er komt een uurloon binnen UITVOERDER (max 10 chars)
            // Strategie
            // Test eerst of het lukt met het prefix karakter, als dat niet lukt dan
            //   Voeg een karakter [A-Z][0-1] toe tot maximaal 10 posities toe en test of deze al bestaat
            //   Begin met aanvullen aan het eind (tot max 10 chars)
            //    Als dat niet meer kan ga dan vanaf uurloonCodeOrg.Length - 1 naar links 
            bool aanvullen = true;
            int startLengte = uurloonCodeOrg.Length;
            string basisUurloonCode = uurloonCodeOrg.Trim();


            if (uurloonCodeOrg.Length < 10)
            {
                string uurloonCodeMetPrefix = basisUurloonCode + prefix;
                if (!uurloonVzl.HeeftUurloon(uurloonCodeMetPrefix))
                {
                    uurloonCode = uurloonCodeMetPrefix;
                }
            }

            if (uurloonCode == null)
            {
                int tekenIndex = 0;
                string tekens = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";//NIETVERTALEN)
                do
                {
                    uurloonCode = basisUurloonCode + tekens[tekenIndex++].ToString();
                    if (tekenIndex >= tekens.Length)
                    {
                        tekenIndex = 0;
                        if (uurloonCode.Length == BUurloonB.c_UlnCdeLen && aanvullen)
                        {
                            aanvullen = false;
                            startLengte--;
                            basisUurloonCode = uurloonCodeOrg.Substring(0, startLengte);
                        }
                        else
                        {
                            if (aanvullen)
                            {
                                basisUurloonCode = uurloonCode;
                            }
                            else
                            {
                                startLengte--;
                                basisUurloonCode = uurloonCodeOrg.Substring(0, startLengte);
                            }
                        }
                    }
                } while (uurloonVzl.HeeftUurloon(uurloonCode));
            }
            return uurloonCode;
        }

