        public static BBegroting VoorbeeldBegroting(bool metBtwRekenen)
        {
            if (s_VoorbeeldBegroting == null)
            {
                BBegroting bgr = new BBegroting(ProjectResources.TradC116, GeefStdBasisValuta(), new BegrotingMaxIdBepaler());
                bgr.RegistreerOpdrachten(false);
                if (metBtwRekenen)
                {
                    // NB Kan hier nietr de "bgr._BtwToepassen = true;" gebruiken want die gaat rekeken en geeft dan logboekmeldingen
                    BBegrotingsGegeven bgv = bgr._Bgv.MaakBegrotingsGegeven(BBegrotingsGegeven.c_BtwToepassen, EGgvTpe.Tekst, "Btw toepassen");//NIETVERTALEN
                    bgv._Wde = Constants.Waar;
                }

                // Maak begrotingsregels aan
                BElement hoofdstuk = bgr.MaakElement(BBegroting.c_RElId, true);   // true: achteraan toevoegen in de begroting
                BElement subHoofdstuk = bgr.MaakElement(hoofdstuk._Id, true);
                BElement paragraaf = bgr.MaakElement(subHoofdstuk._Id, true);
                BElement element = bgr.MaakElement(paragraaf._Id, true);
                BKostenpost? kostenpost = bgr.MaakKostenpost(element._Id, true);

                bgr.MaakOpslagpost(element._Id, true);
                bgr.MaakCommentaar(element._Id, true);
                // toekomst:
                bgr.MaakKostenpost(BBegroting.c_RElId, true);   // Losse kostenpost

                // Voeg wat gegevens toe
                for (int index = bgr._Stu._Aantal - 1; index > 0; index--)
                    bgr._Stu[index]._Regel?.VoorbeeldGegevens();

                string ulnCde = ProjectResources.TradC117;
                BUurloonBVzl ulbVzl = bgr.GeefUurloonBVzl();
                ulbVzl.VerwijderUurloon(string.Empty);   // Standaarduurloon staat vooraan, vervang deze
                BUurloonB ulb = new BUurloonB(ulnCde, new BBedrag(bgr._VltId, 19.50), 0.0);
                ulb._Oms = ProjectResources.TradC1171;
                ulbVzl.ToevoegenUurloon(ulb);
                IList<BValutaDeco> bvaVzl = bgr.BegrotingsValuta;
                s_VoorbeeldBegroting = bgr;
                kostenpost?.WijzigUurloon(ulnCde);
                bgr.RegistreerOpdrachten(true);   // houdt in: bgr.Rekenen(ERekendiepte.Volledig);
            }
            return s_VoorbeeldBegroting;
        }
