        public static BDocValuta GeefStdBasisValuta()
        {
            List<BValutaDeco> bva = new();
            BValutaDeco? basisVal = BValuta.GeefBasisValuta(); // Geef de StamValuta met koers 1.00: Dit is een StamValuta
            basisVal ??= BValuta.GeefValuta(0);          // Dit is een StamValuta

