    public int GeefAantalDocumentTekstRegels(ETekstType tekstType)
    {
        string? tekst = null;
        switch (tekstType)
        {
            case ETekstType.Voorblad: tekst = m_RawVoorblad; break;
            case ETekstType.Inschrijfbiljet: tekst = m_RawInschrijfBiljet; break;
        }

        int aantalRegels = 0;
        if (!string.IsNullOrEmpty(tekst))
        {
            int index = 0;
            while ((index = tekst.IndexOf(Environment.NewLine, index)) >= 0)
            {
                aantalRegels++;
                index++;
                if (index >= tekst.Length)
                    break;
            }
        }
        return aantalRegels;
    }
    /// <summary>Geef het percentage van de raw code 960010 of 960020
    /// </summary>
    /// <param name="code">De code waar het percentage van gevraagd wordt</param>
    /// <returns>Alleen bij 960010 of 960020 het percentage, in alle andere gevallen 0.0</returns>
    public double GeefPercentage(string code)
    {
        double percentage = 0.0;
        switch (code)
        {
            case RawRegelgeving.c_RawRawBijdrageCode:
                percentage = _RawPercentage;
                break;
            case RawRegelgeving.c_RawFcoBijdrageCode:
                percentage = _FcoPercentage;
                break;
            case RawRegelgeving.c_RawVsiBijdrageCode:
                percentage = _VsiPercentage;
                break;
        }
        return percentage;
    }
    /// <summary>Bepaal of een code van een speciale raw code is (960010 of 960020)
    /// </summary>
    /// <param name="code">Te onderzoeken code</param>
    /// <returns>True indien de code een speciale raw opslag is anders false</returns>
    public static EType GeefRawOpslagType(string code)
    {
        EType opslagType = EType.Geen;
        switch (code)
        {
            case RawRegelgeving.c_RawRawBijdrageCode:
                opslagType = EType.Raw;
                break;
            case RawRegelgeving.c_RawFcoBijdrageCode:
                opslagType = EType.Fco;
                break;
            case RawRegelgeving.c_RawVsiBijdrageCode:
                opslagType = EType.Vsi;
                break;
        }
        return opslagType;
    }

    private RawRegelgeving GetRawRegelgeving() => RawRegelgeving.GetRawRegelgeving(_Jaarversie, _Contractvorm);

    private static ERawBijzonderRegelType GeefRawRegelType(string code, RawJaarversie jaarversie)
    {
        ERawBijzonderRegelType tpe = ERawBijzonderRegelType.Geen;
        switch (code)
        {
            case RawRegelgeving.c_RawRawBijdrageCode:
                tpe = ERawBijzonderRegelType.Raw;
                break;
            case RawRegelgeving.c_RawFcoBijdrageCode:
                tpe = ERawBijzonderRegelType.Fco;
                break;
            case RawRegelgeving.c_RawVsiBijdrageCode:
                tpe = ERawBijzonderRegelType.Vsi;
                break;
            case RawRegelgeving.c_RawTotEenmaligeKostenCodeTem2015:
                if (jaarversie <= RawJaarversie.v2015)
                    tpe = ERawBijzonderRegelType.TotEenmaligeKosten;
                break;
            case RawRegelgeving.c_RawUitvoeringsKostenCode:
                tpe = ERawBijzonderRegelType.UitvoeringKosten;
                break;
            case RawRegelgeving.c_RawWRCode:
