        #region Algemene methods
        /// <summary>Geef een lijst van (fout) meldingen betreffende deze combinatie van gegevens
        /// </summary>
        /// <returns>Een lijst met meldingen</returns>
        public List<string> GeefMeldingen()
        {
            List<string> meldingen = new List<string>();

            if (m_InBegroting && m_InBegrotingBlad)
            {
                string melding = string.Format(ProjectResources.TradB2411, m_Code);
