            m_InBegroting = inBegroting;
            m_StuIndex = stuIndex;
        }
        /// <summary>Vul het begrotingsbladdeel van de gegevens
        /// </summary>
        /// <param name="inBegrotingBlad">Indicatie of deze regel in het begrotingsblad voorkomt</param>
        public void ZetStatusBgrBld(bool inBegrotingBlad, string code)
        {
            if (string.IsNullOrEmpty(m_Code))
            {
                // Deze situatie komt voor als de raw codes wel in het begrotingsblad staan maar niet
                // in de begroting. In dat geval de code van het begrotingsblad overnemen
                m_Code = code;
            }
            m_InBegrotingBlad = inBegrotingBlad;
        }
        #endregion Algemene methods
    }
    #endregion class BRawControle


