        /// <summary>Bepaal of een valuta in gebruik is in de begroting
        /// </summary>
        /// <param name="valutaId">De id van de valuta welke bepaald moet worden</param>
        /// <returns>true indien de valutaid in een middel gebruikt wordt of als het de basisvaluta is anders false</returns>
        public bool IsValutaInGebruik(int valutaId)
        {
            bool valutaInGebruik = false;

            if (valutaId == _VltId)
            {
                valutaInGebruik = true; // De basisvaluta is altijd in gebruik en mag niet verwijderd worden
            }
            else
            {
                foreach (BMiddel middel in _Mid)
                {
                    if (middel._VltId == valutaId)
                    {
                        valutaInGebruik = true;
                        break;
                    }
                }
            }
            return valutaInGebruik;
        }

