        private IBegrotingsRegel? MaakNieuweKostenpost(int stuIndex)
        {
            BStructuurRegel sturgl = _Stu[stuIndex];
            int nieuwid = GeefNieuwId();
            BKostenpost kostenpost = MaakOntbrekendeKostenpost(nieuwid);
            var sturegelnieuw = new BStructuurRegel(kostenpost, sturgl._PrtId);
            sturegelnieuw._Regel?.Begroting = this;
            sturegelnieuw._Regel?.ZetMutatieStatus(BewaarItemMutatieStatus.Nieuw);
            sturegelnieuw._Niveau = sturgl._Niveau;
            if (_structuurStatusFout.ControleerBegrotingStatus == EControleerBegrotingStatus.ControlerenEnRepareren)
            {
                LogboekMelding(string.Format(ProjectResources.TradA0024127261, sturgl._Id, sturegelnieuw._Id));
                _structuurStatusFout.VoegStatusToe(EStructuurStatusFout.Kostenpost);

            }
            _Stu.Vervangen(sturegelnieuw, stuIndex);

            return sturegelnieuw._Regel;
        }

        private void WijzigKinderen(int vanElementIndex, int oudeID, int nieuweID, int vanniveau)
        {
            for (int stuIndex = vanElementIndex + 1; stuIndex < _Stu._Aantal; stuIndex++)
            {
                if (_Stu[stuIndex]._Niveau <= vanniveau)
                    break;

                if (_Stu[stuIndex]._PrtId == oudeID)
                {
                    BStructuurRegel stuRegel = new BStructuurRegel(_Stu[stuIndex]._Regel, nieuweID);
                    stuRegel._Niveau = _Stu[stuIndex]._Niveau;
                    _Stu.Vervangen(stuRegel, stuIndex);
                }
            }
        }

