    internal bool IsSubtotaal9VanRO(IBegroting begroting, int id)
    {
        bool subtotaal9VanRO = false;
        if (RawIsRaamovereenkomst())
        {
            BElement? parentElement = begroting.GeefParentElement(id, out _);
            subtotaal9VanRO = parentElement._CclCde == "9";
        }
        return subtotaal9VanRO;
    }

    internal void MaakBruto(BBegroting bgr, out bool rawVttIdVerwijderd)
    {
        #region Info Discussie WJ/SGB
        /*
           Zie bijlage bij workitem #15053
           Van: Wil Jong;  Verzonden: vrijdag 8 juli 2011 8:37; Aan: Sibrand Brouwer
           Onderwerp: RE: #15053 RAW begroting opslaan als bruto begroting / #14170 Extra zoekboom projectmiddelen 
           Sibrand, Ja, dat klopt en is nu eenmaal het gevolg van de bewust gekozen rekensystematiek voor de gehele begroting of een bepaald element.
