    #region class BRawControle
    /// <summary>Class voor het controleren van de status van een speciale raw code
    /// </summary>
    private class BRawControle
    {
        #region Fields
        /// <summary>Code van de raw regel (939990/949990/960010/960020)
        /// </summary>
        private string m_Code = string.Empty;
        /// <summary>Indicatie of deze code in de begroting voorkomt
        /// </summary>
        private bool m_InBegroting;
        /// <summary>Indicatie of deze code in het begrotingsblad voorkomt
        /// </summary>
        private bool m_InBegrotingBlad;
        /// <summary>De stuindex van de regel waar deze code in de begroting voorkomt
        /// </summary>
        private int m_StuIndex = -1;
