    public bool VeldString(string waarde, EGegeven gegevenNr, int stuIndex)
    {
        m_Structuur.LeesBegrotingsRegel(stuIndex);
        if (AlleenLezen())
        {
            m_Structuur[stuIndex]._Regel.VerversUi();
            return true;
        }
        BOpdracht? opdracht = m_Begroting.WijzigStringBgrRegel(true, stuIndex, gegevenNr, waarde, OpdrachtValidator, out bool lokaal); //!m_Filter
        if (opdracht == null)
        {
            // Wijziging is niet uitgevoerd
            m_Structuur[stuIndex]._Regel.VerversUi();   // Deze regel moet ververst worden om de oude waarde weer te voorschijn te toveren
            return true;
        }
        else opdracht.SetView(m_ViewNr);
        return !lokaal;
    }
