           -      Herbereken totaal vanuit eenheidsprijs
           -      Vastprijs indicatie (volgens mij gaat dit ook bij niet RAW fout)
           -      Productiefactor?
           -      …….
        */
        #endregion Info Discussie WJ/SGB

        rawVttIdVerwijderd = false;
        ERawBeginStaart rawBeginStaart = ERawBeginStaart.Geen;
        BStructuurRegel stuRegel;
        for (int stuIndex = bgr._Stu._Aantal - 1; stuIndex > 0; stuIndex--)
        {
            stuRegel = bgr._Stu[stuIndex];
            ERawBeginStaart type = RawIsBeginRawStaart(stuRegel);
            if (type != ERawBeginStaart.Geen)
            {
                rawBeginStaart |= type;
                if (type == ERawBeginStaart.Code9) break;
                if (rawBeginStaart != ERawBeginStaart.Geen && type == ERawBeginStaart.Geen) break;
            }
        }


        if (rawBeginStaart != ERawBeginStaart.Geen)
        {
            // Er is een Raw hoofdstuk 9 gevonden: Alle elementen hiervan verwijderen
            for (int stuIndex = bgr._Stu._Aantal - 1; stuIndex > 0; stuIndex--)
            {
                stuRegel = bgr._Stu[stuIndex];
                IBegrotingsRegel bgrRegel = stuRegel._Regel;
                if (bgrRegel._Id == bgr._VttId)
                {
                    rawVttIdVerwijderd = true;
                }
                if (stuRegel._Tpe == EOnderbouwing.Element)
                {
                    bgr.VerwijderBegrotingsRegel(stuIndex, EBgrRegelVerwijderen.Onderbouwing);
                }

                // Stop als we Hoofdstuk "9" / "91" gehad hebben
                ERawBeginStaart type = RawIsBeginRawStaart(stuRegel);
                if (type == ERawBeginStaart.Code9)
                {
                    break;
                }
                if (type == ERawBeginStaart.Code91 && ((rawBeginStaart & ERawBeginStaart.Code9) == 0))
                {
                    break;
                }
            }
        }
    }

