    public static IFCTabel VoorbeeldTabel()
    {
        if (s_VoorbeeldTabel == null)
        {
            BBegroting bgr = BBegroting.VoorbeeldBegroting(false);

            // Maak een IFCTabel aan mbv de voorbeeldbegroting
            s_VoorbeeldTabel = new BBegrotingTabel(bgr, EViewKey .Leeg);   // -1: viewNr
        }
        return s_VoorbeeldTabel;
    }

    #region IBijzondereTabel Members

    /// <summary>
    /// Geef het nummer van de kolom waarin voor een bepaalde (of alle) rijsoort(-en) een bijzonderheid geldt
    /// </summary>
    /// <param name="bijzonderheid">Omschrijving van de specialiteit van de kolom</param>
    /// <param name="specificatie">Specificatie-object, of null bv BOpmaakRijSoort,int,...</param>
    /// <returns>Nummer van de kolom</returns>
    [System.Diagnostics.CodeAnalysis.SuppressMessage("Microsoft.Performance", "CA1800:DoNotCastUnnecessarily")]
    public int BijzondereKolom(string bijzonderheid, object? specificatie)
    {
        if (bijzonderheid == BApplicatie.c_BijzklmUitsmeerbaar)            // Kolom met tekst die uitgesmeerd kan worden over andere kolommen
            return BijzklmUitsmeerbaar(specificatie);
        if (bijzonderheid == BApplicatie.c_BijzklmInspringen)              // Kolom waarvan de tekst inspringt
            return BijzklmInspringen(specificatie);
        if (bijzonderheid == BApplicatie.c_BijzklmInitialiseren || bijzonderheid == BApplicatie.c_BijzklmControlecode)   // Kolom waarvan de waarden tot een speciale set van waarden moeten behoren. De kolom is wel wijzigbaar maar niet vrij wijzigbaar, niet elke waarde kan worden geaccepteerd.
            return BijzklmInitialiserenBijzklmControlecode(specificatie);
        if (bijzonderheid == BApplicatie.c_BijzklmStuurcode)
            return BijzklmStuurcode(specificatie);
        if (bijzonderheid == BApplicatie.c_BijzklmKopieer)
            return BijzklmKopieer(specificatie);
        return -1;
    }
    private static int BijzklmUitsmeerbaar(object? specificatie)
    {
        BOpmaakRijSoort? rs = specificatie as BOpmaakRijSoort;

        if (rs?._RijSoort == 'C')                          // Commentaarregel
            return (int)EGegeven.oms;    // Omschrijvingkolom
        return -1;
    }
    private static int BijzklmInspringen(object? specificatie)
    {
        Debug.Assert(specificatie is int, "BBegrotingUi.BijzondereKolom Specificatie argument is geen int ");

        int tabelkolomnr = (int)specificatie;
        if (tabelkolomnr == (int)EGegeven.cclcde ||
           tabelkolomnr == (int)EGegeven.oms ||
           tabelkolomnr == (int)EGegeven.loccde)
            return tabelkolomnr;
        return -1;
    }

    private static int BijzklmInitialiserenBijzklmControlecode(object? specificatie)
    {
        Debug.Assert(specificatie is int, "BBegrotingUi.BijzondereKolom Specificatie argument is geen int ");
        int tabelkolomnr = (int)specificatie;
        if (tabelkolomnr == (int)EGegeven.ulnbdr)
            return tabelkolomnr;
        return -1;
    }

    private static int BijzklmStuurcode(object? specificatie)
    {
        Debug.Assert(specificatie is string, "BBegrotingUi.BijzondereKolom Specificatie argument is geen string ");

        var stuurcode = (specificatie as string)?.Trim();
        if (stuurcode != null && stuurcode.Length > 0)
        {
            // returnwaarde
            // -1 = Geen controle uitgevoerd (niet nodig) 
            //  0 = Controle uitgevoerd, resultaat "false"
            //  1 = Controle uitgevoerd, resultaat "true"
            if (c_sAlleStuurcodes.Contains(stuurcode))
                return 1;
            else return 0;
        }
        return -1;
    }

    private static int BijzklmKopieer(object? specificatie)
    {
        int tabelkolomnr = (int)specificatie;
        if (tabelkolomnr == (int)BBegrotingsRegel.EGegeven.uurnrmtpe || tabelkolomnr == (int)BBegrotingsRegel.EGegeven.BeschikbaarheidsStatus || tabelkolomnr == (int)BBegrotingsRegel.EGegeven.BlokkeerStatus)
            return tabelkolomnr;
        return -1;
    }

    #endregion

    #region PrijzenBoek

    /// <summary>Onthouden van de laatst opgezochte referentie stu index. Vaak worden de achtereenvolgende gegevens van
    /// eenzelfde referentieregel opgevraagd
    /// </summary>
    protected int m_ReferentieRegelStuIndex = -1;

    /// <summary>Haal de overeenkomstige waarde van een opgegeven kolom uit de referentie "Prijzen"
    /// De waarde wordt opgezocht op basis van overeenkomende code
    /// Bij tabelkolomnummer "VerschilTabelKolomNr" wordt het verschil tussen begrotin en referentie gegeven
    /// </summary>
    /// <param name="bgrRegel">De originele begrotingsregel</param>
    /// <param name="kolomNr">Het gevraagde gegeven (tabelkolomnummer)</param>
    /// <param name="geenWaarde">Indicatie geen waarde aanwezig</param>
    /// <returns>De gevonden waarde anders 0.0 (geenWaarde is dan true)</returns>
    private double ReferentieVeldDouble(IBegrotingsRegel bgrRegel, int kolomNr, out bool geenWaarde)
    {
        geenWaarde = false;

        if (m_VerschilMode == EVerschilMode.Elementen && bgrRegel._OnderbouwingType == EOnderbouwing.Kostenpost)
        {
            geenWaarde = true;
            return 0.0;
        }
        double waarde = 0.0;

        IBegrotingsRegel? refRegel = GeefReferentieRegel(bgrRegel);

        if (refRegel != null)
        {
            if (kolomNr != BTabelOpmaak.c_VerschilTabelKolomNr)
            {
                waarde = refRegel.GeefDouble((EGegeven)(kolomNr - BTabelOpmaak.c_EersteVerschilTabelKolomNr), out geenWaarde);
            }
            else
            {
                double bgrTotaal = bgrRegel.GeefDouble(BBegrotingsRegel.EGegeven.btoaks, out geenWaarde);
                if (!geenWaarde)
                {
                    double refTotaal = refRegel.GeefDouble(BBegrotingsRegel.EGegeven.btoaks, out geenWaarde);
                    waarde = refTotaal - bgrTotaal;
                }
            }
        }
        return waarde;
    }

    /// <summary>Haal de overeenkomstige waarde van een opgegeven kolom uit de referentie "Prijzen"
    /// De waarde wordt opgezocht op basis van overeenkomende code
    /// </summary>
    /// <param name="bgrRegel">De originele begrotingsregel</param>
    /// <param name="kolomNr">Het gevraagde gegeven (tabelkolomnummer)</param>
    /// <param name="geenWaarde">Indicatie geen waarde aanwezig</param>
    /// <returns>De gevonden waarde anders 0 (geenWaarde is dan true)</returns>
    private int ReferentieVeldInteger(IBegrotingsRegel bgrRegel, int kolomNr, out bool geenWaarde)
    {
        geenWaarde = false;
        IBegrotingsRegel? refRegel = GeefReferentieRegel(bgrRegel);
        if (refRegel != null)
            return refRegel.GeefInteger((EGegeven)(kolomNr - BTabelOpmaak.c_EersteVerschilTabelKolomNr));

        geenWaarde = true;
        return 0;
    }

    /// <summary>Haal de overeenkomstige waarde van een opgegeven kolom uit de referentie "Prijzen"
    /// De waarde wordt opgezocht op basis van overeenkomende code
    /// </summary>
    /// <param name="bgrRegel">De originele begrotingsregel</param>
    /// <param name="kolomNr">Het gevraagde gegeven (tabelkolomnummer)</param>
    /// <param name="geenWaarde">Indicatie geen waarde aanwezig</param>
    /// <returns>De gevonden waarde anders DateTime.now (geenWaarde is dan true)</returns>
    private DateTime ReferentieVeldDatum(IBegrotingsRegel bgrRegel, int kolomNr, out bool geenWaarde)
    {
        geenWaarde = false;
        IBegrotingsRegel? refRegel = GeefReferentieRegel(bgrRegel);
        if (refRegel != null)
            return refRegel.GeefDatum((EGegeven)(kolomNr - BTabelOpmaak.c_EersteVerschilTabelKolomNr), out geenWaarde);

        geenWaarde = true;
        return DateTime.Now;
    }

    /// <summary>Haal de overeenkomstige waarde van een opgegeven kolom uit de referentie "Prijzen"
    /// De waarde wordt opgezocht op basis van overeenkomende code
    /// </summary>
    /// <param name="bgrRegel">De originele begrotingsregel</param>
    /// <param name="kolomNr">Het gevraagde gegeven (tabelkolomnummer)</param>
    /// <returns>De gevonden waarde anders string.Empty</returns>
    private string ReferentieVeldString(IBegrotingsRegel bgrRegel, int kolomNr)
    {
        IBegrotingsRegel? refRegel = GeefReferentieRegel(bgrRegel);
        if (refRegel != null)
        {
            var gegeven = (EGegeven)(kolomNr - BTabelOpmaak.c_EersteVerschilTabelKolomNr);
            if(gegeven == EGegeven.stk && refRegel is BElement element)
                return GeefReferentieElementStuurcode(element);

            return refRegel.GeefString(gegeven, true);
        }

        return string.Empty;
    }

    /// <summary>Zoek een regel in de referentie op basis van de code van een opgegeven regel
    /// </summary>
    /// <param name="bgrRegel">De originele begrotingsregel</param>
    /// <returns>De gevonden regel en anders null</returns>
    private IBegrotingsRegel? GeefReferentieRegel(IBegrotingsRegel bgrRegel)
    {
        if (string.IsNullOrEmpty(bgrRegel._CclCde))
            return null;

        IBegroting? prijzenBoek = m_Begroting._PrijzenBoek;
        if (prijzenBoek == null)
            return null;

        IStructuur prijzenboekStu = prijzenBoek._Stu;

        if (m_ReferentieRegelStuIndex > 0)
        {
            BStructuurRegel stuRegel = prijzenboekStu.LeesBegrotingsRegel(m_ReferentieRegelStuIndex);
            if (stuRegel._Regel._CclCde == bgrRegel._CclCde)
                return stuRegel._Regel;
        }

        for (int stuIndex = 0; stuIndex < prijzenboekStu._Aantal; stuIndex++)
        {
            BStructuurRegel stuRegel = prijzenboekStu.LeesBegrotingsRegel(stuIndex);
            if (stuRegel._Regel._CclCde == bgrRegel._CclCde)
            {
                m_ReferentieRegelStuIndex = stuIndex;
                return stuRegel._Regel;
            }
        }

        return null;
    }

    private string GeefReferentieElementStuurcode(BElement element)
    {
        const string DefaultStuurcode = "+";
        if (m_ReferentieRegelStuIndex <= 0) return DefaultStuurcode;
        
        IBegroting? prijzenBoek = m_Begroting._PrijzenBoek;
        if (prijzenBoek == null) return DefaultStuurcode;

        var prijzenboekStructuur = prijzenBoek._Stu;
        var referentieRegel = prijzenboekStructuur[m_ReferentieRegelStuIndex];
        var niveau = referentieRegel._Niveau;
        if(niveau < 1)
            niveau = prijzenboekStructuur.GeefNiveau(m_ReferentieRegelStuIndex);

        return element.GeefNiveauIndicatie(niveau);
    }

    #endregion PrijzenBoek

    #region IHeeftHierarchie Members
    public bool IsLaagsteNiveau(int rijNr)
    {
        bool laagsteNiveau = false;
        int stuIndex = StuIndex(rijNr);
        switch (m_Structuur[stuIndex]._Tpe)
        {
            case EOnderbouwing.Kostenpost:
            case EOnderbouwing.Commentaar:
            case EOnderbouwing.Opslagpost:
                laagsteNiveau = true;
                break;
        }
        return laagsteNiveau;
    }
    public string OvernemenTekst()
    {
        return ProjectResources.TradC117231; // Startwaarde vanuit elementregel overnemen in kostenposten.
    }

